import requests

# Step 1: Trigger the hook for automatic alerts
hook_response = requests.post("https://api.socbench.example/trigger-hook")
if hook_response.status_code != 200:
    raise Exception("Failed to trigger the hook")

# Step 2: Retrieve all logged cybersecurity threats
threats_response = requests.get("https://api.socbench.example/threats")
if threats_response.status_code != 200:
    raise Exception("Failed to retrieve threats")
threats = threats_response.json()

# Step 3: Retrieve all alert rules
alerts_response = requests.get("https://api.socbench.example/alerts")
if alerts_response.status_code != 200:
    raise Exception("Failed to retrieve alerts")
alerts = alerts_response.json()

# Step 4: Update specific alert rules based on identified conditions
for alert in alerts:
    # Example condition: Update alerts related to specific threats
    for threat in threats:
        if "vulnerability" in threat.get("details", "").lower():
            updated_alert_data = {
                "name": alert["name"],
                "status": "updated",
                "conditions": alert["conditions"] + ["vulnerability detected"]
            }
            update_response = requests.put(
                f"https://api.socbench.example/alerts/{alert['id']}",
                json=updated_alert_data
            )
            if update_response.status_code != 200:
                raise Exception(f"Failed to update alert {alert['id']}")

# Step 5: Delete unnecessary alerts
for alert in alerts:
    if "obsolete" in alert.get("conditions", []):
        delete_response = requests.delete(f"https://api.socbench.example/alerts/{alert['id']}")
